/**
 * Mini Baryonyx (Tipo Agua) — Versión Chibi / Cría compañera de dinosaurio.
 * Basado en el arte oficial de Dinosaur King:
 *   assets/dinos/arte/agua/baryonyx_izq.webp
 *
 * Características anatómicas del Baryonyx:
 *   - Terópodo bípedo semi-acuático tierno, ágil y carnívoro.
 *   - Hocico alargado tipo cocodrilo con roseta premaxilar ensanchada en forma de cuchara,
 *     escotadura subrostral, cresta nasal media y doble hilera de dientes cónicos entrelazados.
 *   - Lomo continuo y perfectamente suavizado sin cortes ni saltos bruscos hacia el cuello.
 *   - Brazos con la icónica y enorme garra curva del pulgar (GarraPulgarBaryonyx).
 *   - Patas bípedas musculosas con garras afiladas y espolón posterior.
 *   - Cola estirada horizontalmente (estilo Amargasaurus) para contrapeso bípedo.
 *   - Malla 100% cerrada y hermética (cero huecos, extremidades con cúpulas internas).
 *   - Proyección lateral de la textura oficial con color salmón/terracota vivo,
 *     lomo crema y vientre suave continuo.
 *   - Esqueleto y animaciones fluidas (Reposo, Caminar, Rugir con apertura de fauces).
 */
registrarMalla({
  id: "mini_baryonyx",
  categoria: "mini dino",
  nombre: "Mini Baryonyx (Agua)",
  icono: "🦖",
  origen: "assets/dinos/arte/agua/baryonyx_izq.webp",

  construir(M) {
    const g = new THREE.Group();
    const LADOS = [-1, 1];
    const L = (s) => (s > 0 ? "I" : "D");
    const V = (x, y, z) => new THREE.Vector3(x, y, z);
    const grad = Math.PI / 180;
    const cr = (p0, p1, p2, p3, t) => 0.5 * ((2 * p1) + (-p0 + p2) * t
      + (2 * p0 - 5 * p1 + 4 * p2 - p3) * t * t + (-p0 + 3 * p1 - 3 * p2 + p3) * t * t * t);

    // ---------------- UTILIDADES GEOMÉTRICAS ----------------
    const suave = (a, b, x) => {
      const t = Math.max(0, Math.min(1, (x - a) / (b - a)));
      return t * t * (3 - 2 * t);
    };

    function rejilla(pos, cols, rows, nombre) {
      const idx = [];
      for (let r = 0; r < rows; r++) {
        for (let c = 0; c < cols; c++) {
          const a = r * (cols + 1) + c;
          const b = a + cols + 1;
          idx.push(a, b, a + 1, b, b + 1, a + 1);
        }
      }
      const geo = new THREE.BufferGeometry();
      geo.setAttribute("position", new THREE.Float32BufferAttribute(pos, 3));
      geo.setIndex(idx);
      return M.pieza(geo, nombre, cols, rows);
    }

    function bloque(x, y, z, rx, ry, rz, curva = 0.5, nombre = "Bloque", segA = 14, segB = 10) {
      const sW = M.seg(segA, 8);
      const sH = M.seg(segB, 6);
      const geo = new THREE.SphereGeometry(1, sW, sH);
      const pos = geo.attributes.position;
      for (let i = 0; i < pos.count; i++) {
        let px = pos.getX(i), py = pos.getY(i), pz = pos.getZ(i);
        const d = Math.pow(Math.abs(px), 2.5) + Math.pow(Math.abs(py), 2.5) + Math.pow(Math.abs(pz), 2.5);
        const f = 1 / Math.pow(d, 1 / 2.5);
        px = (px * (1 - curva) + (px * f) * curva) * rx;
        py = (py * (1 - curva) + (py * f) * curva) * ry;
        pz = (pz * (1 - curva) + (pz * f) * curva) * rz;
        pos.setXYZ(i, px, py, pz);
      }
      geo.translate(x, y, z);
      return M.pieza(geo, nombre, sW, sH);
    }

    function punta(camino, radio, nombre, segL = 12, segR = 10) {
      const c = M.curva(camino);
      const tSeg = M.seg(segL, 8);
      const rSeg = M.seg(segR, 6);
      const geo = new THREE.TubeGeometry(c, tSeg, 1, rSeg, false);
      const pos = geo.attributes.position;
      const P = new THREE.Vector3();
      for (let i = 0; i <= tSeg; i++) {
        const t = i / tSeg;
        c.getPointAt(t, P);
        const r = radio * Math.max(0.001, 1 - t * 0.96);
        for (let j = 0; j <= rSeg; j++) {
          const k = i * (rSeg + 1) + j;
          pos.setXYZ(k,
            P.x + (pos.getX(k) - P.x) * r,
            P.y + (pos.getY(k) - P.y) * r,
            P.z + (pos.getZ(k) - P.z) * r
          );
        }
      }
      return M.coserNormales(M.pieza(geo, nombre, rSeg, tSeg));
    }

    function almendra(rx, ry, rz, nombre = "Almendra", segA = 16, segB = 12) {
      const sW = M.seg(segA, 10);
      const sH = M.seg(segB, 8);
      const geo = new THREE.SphereGeometry(1, sW, sH);
      const pos = geo.attributes.position;
      for (let i = 0; i < pos.count; i++) {
        let px = pos.getX(i), py = pos.getY(i), pz = pos.getZ(i);
        const k = 1 - Math.abs(px) * 0.35;
        px *= rx * 1.05;
        py *= ry * k;
        pz *= rz * k;
        pos.setXYZ(i, px, py, pz);
      }
      return M.pieza(geo, nombre, sW, sH);
    }

    // ---------------- 1. CUERPO CONTINUO BÍPEDO 100% CERRADO ----------------
    // Eje longitudinal con hocico largo tipo cocodrilo, roseta espatulada y transición suave torso-cuello:
    // [z, y, semiancho, altoHaciaArriba, altoHaciaAbajo, forma]
    const EJE = [
      [-0.76, 0.58, 0.000, 0.000, 0.000, 2.1],  // Punta cola cerrada curvada suave arriba
      [-0.72, 0.56, 0.035, 0.038, 0.035, 2.1],
      [-0.60, 0.54, 0.065, 0.070, 0.065, 2.1],  // Cola media estirada hacia atrás
      [-0.46, 0.53, 0.105, 0.115, 0.105, 2.1],
      [-0.32, 0.53, 0.145, 0.155, 0.145, 2.2],  // Base de la cola
      [-0.16, 0.54, 0.185, 0.230, 0.185, 2.3],  // Cadera / pelvis bípeda esbelta
      [ 0.02, 0.55, 0.195, 0.240, 0.190, 2.4],  // Torso esbelto / vientre atlético
      [ 0.18, 0.55, 0.180, 0.230, 0.175, 2.3],  // Pecho esbelto
      [ 0.28, 0.60, 0.150, 0.185, 0.145, 2.2],  // Base del cuello (transición gradual)
      [ 0.36, 0.68, 0.125, 0.150, 0.125, 2.1],  // Cuello en arco S
      [ 0.44, 0.77, 0.115, 0.135, 0.115, 2.2],  // Nuca
      [ 0.52, 0.81, 0.125, 0.140, 0.110, 2.3],  // Cráneo chibi y zona de ojos
      [ 0.62, 0.79, 0.095, 0.100, 0.078, 2.2],  // Nacimiento del hocico cocodrilo
      [ 0.72, 0.77, 0.062, 0.078, 0.062, 2.2],  // Rostro medio alargado estrecho
      [ 0.82, 0.755, 0.055, 0.070, 0.055, 2.2], // Escotadura subrostral cóncava
      [ 0.88, 0.750, 0.065, 0.066, 0.052, 2.2], // Roseta premaxilar ensanchada (cuchara de cocodrilo)
      [ 0.91, 0.748, 0.038, 0.040, 0.032, 2.1], // Punta del hocico
      [ 0.93, 0.746, 0.000, 0.000, 0.000, 2.0]  // Cierre hermético en domo redondeado
    ];

    const ejeCurva = new THREE.CatmullRomCurve3(EJE.map(([z, y]) => V(0, y, z)), false, "centripetal");
    ejeCurva.arcLengthDivisions = 1200;
    const LARGO = ejeCurva.getLength();

    function seccion(u) {
      const f = ejeCurva.getUtoTmapping(u) * (EJE.length - 1);
      const i = Math.min(EJE.length - 2, Math.floor(f));
      const t = f - i;
      const a = EJE[Math.max(0, i - 1)];
      const b = EJE[i];
      const c = EJE[i + 1];
      const d = EJE[Math.min(EJE.length - 1, i + 2)];
      return [2, 3, 4, 5].map((j) => Math.max(0, cr(a[j], b[j], c[j], d[j], t)));
    }

    const X = V(1, 0, 0);
    function marcoEje(u) {
      const P = ejeCurva.getPointAt(u);
      const T = ejeCurva.getTangentAt(u);
      // Suavizamos el ángulo de inclinación de la sección en Y-Z para que las rebanadas
      // no se plieguen hacia atrás en la transición torso-cuello, eliminando cualquier corte o pared vertical
      const ang = Math.atan2(T.y, T.z);
      const angSuave = ang * 0.35;
      const U = V(0, Math.cos(angSuave), -Math.sin(angSuave));
      return { P, T, U };
    }

    function uCercano(p, desde = 0, hasta = 1) {
      let mejor = desde;
      let dMin = Infinity;
      for (let k = 0; k <= 400; k++) {
        const u = desde + (hasta - desde) * (k / 400);
        const d = ejeCurva.getPointAt(u).distanceToSquared(p);
        if (d < dMin) { dMin = d; mejor = u; }
      }
      return mejor;
    }

    // Malla continua de alta resolución
    const COLS = M.seg(72, 20);
    const FILAS = M.seg(360, 60);
    const cuerpo = (() => {
      const pos = [];
      for (let r = 0; r <= FILAS; r++) {
        const u = r / FILAS;
        const { P, U } = marcoEje(u);
        const [w, hA, hB, p] = seccion(u);
        const ex = 2 / p;
        const z = P.z;

        // Musculatura de cadera bípeda y cresta baja del lomo
        const muslo = 0.032 * Math.exp(-Math.pow((z + 0.16) / 0.16, 2));
        const crestaLomo = (z > -0.30 && z < 0.40) ? 0.016 * Math.sin((z + 0.30) / 0.70 * Math.PI) : 0;

        for (let c = 0; c <= COLS; c++) {
          const fi = Math.PI + (c / COLS) * Math.PI * 2;
          const s = Math.sin(fi);
          const co = Math.cos(fi);
          const cresta = co > 0.85 ? crestaLomo * Math.pow((co - 0.85) / 0.15, 1.8) : 0;
          const musculo = muslo * Math.pow(Math.abs(s), 1.6);

          const lx = (w + musculo) * Math.sign(s) * Math.pow(Math.abs(s), ex);
          const ly = ((co >= 0 ? hA : hB) + cresta + musculo * 0.3) * Math.sign(co) * Math.pow(Math.abs(co), ex);
          const pto = P.clone().addScaledVector(X, lx).addScaledVector(U, ly);
          pos.push(pto.x, pto.y, pto.z);
        }
      }
      return M.coserNormales(rejilla(pos, COLS, FILAS, "CuerpoBaryonyx"));
    })();

    // ---------------- 2. ESQUELETO Y RIGGING BÍPEDO ----------------
    const PIE_X = 0.17;
    const BRAZO_X = 0.16;

    const HUESOS = [
      ['Raiz', null, 0, 0, 0],
      ['Cadera', 'Raiz', 0, 0.54, -0.16],
      ['Cola1', 'Cadera', 0, 0.53, -0.32],
      ['Cola2', 'Cola1', 0, 0.54, -0.48],
      ['Cola3', 'Cola2', 0, 0.57, -0.64],
      ['Pecho', 'Cadera', 0, 0.55, 0.18],
      ['Cuello1', 'Pecho', 0, 0.68, 0.36],
      ['Cuello2', 'Cuello1', 0, 0.77, 0.44],
      ['Cabeza', 'Cuello2', 0, 0.81, 0.52],
      ['Mandibula', 'Cabeza', 0, 0.76, 0.48],
      ...LADOS.flatMap((s) => [
        // Piernas bípedas
        ['Muslo' + L(s), 'Cadera', s * PIE_X, 0.48, -0.16],
        ['Pierna' + L(s), 'Muslo' + L(s), s * PIE_X, 0.28, -0.10],
        ['Pata' + L(s), 'Pierna' + L(s), s * PIE_X, 0.10, -0.14],
        // Brazos con gran garra
        ['Brazo' + L(s), 'Pecho', s * BRAZO_X, 0.46, 0.16],
        ['Antebrazo' + L(s), 'Brazo' + L(s), s * (BRAZO_X + 0.02), 0.36, 0.24],
        ['Mano' + L(s), 'Antebrazo' + L(s), s * BRAZO_X, 0.28, 0.28]
      ])
    ];

    const hueso = {};
    HUESOS.forEach(([nombre, padre, x, y, z]) => {
      const b = new THREE.Bone();
      b.name = 'Hueso' + nombre;
      b.userData.reposo = V(x, y, z);
      const p = padre ? hueso[padre] : null;
      b.position.set(x, y, z).sub(p ? p.userData.reposo : V(0, 0, 0));
      (p || g).add(b);
      hueso[nombre] = b;
    });
    g.updateMatrixWorld(true);
    const colgar = (nombre, obj) => {
      const h = typeof nombre === 'string' ? hueso[nombre] : nombre;
      if (!h || !obj) return obj;
      h.attach(obj);
      return obj;
    };

    // Vinculación suave de la piel del cuerpo continuo a los huesos
    const uH = (n, d1 = 0.2, d2 = 1) => uCercano(hueso[n].userData.reposo, d1, d2);
    const uCola3 = uCercano(hueso.Cola3.userData.reposo, 0, 0.35);
    const uCola2 = uCercano(hueso.Cola2.userData.reposo, 0.1, 0.45);

    const TRAMOS = [
      [0, 'Cola3'],
      [uCola3, 'Cola2'],
      [uCola2, 'Cola1'],
      [uH('Cola1', 0.15, 0.5), 'Cadera'],
      [uH('Pecho', 0.35, 0.65), 'Pecho'],
      [uH('Cuello1', 0.45, 0.75), 'Cuello1'],
      [uH('Cuello2', 0.60, 0.85), 'Cuello2'],
      [uH('Cabeza', 0.70, 0.95), 'Cabeza']
    ];

    const MEZCLA = 0.15 / LARGO;
    function pesosTramos(u, tramos, mezcla) {
      let k = 0;
      while (k + 1 < tramos.length && u >= tramos[k + 1][0]) k++;
      const res = [[hueso[tramos[k][1]], 1]];
      if (k + 1 < tramos.length) {
        const w = suave(-mezcla, mezcla, u - tramos[k + 1][0]);
        if (w > 0) { res[0][1] = 1 - w; res.push([hueso[tramos[k + 1][1]], w]); }
      }
      if (k > 0) {
        const w = 1 - suave(-mezcla, mezcla, u - tramos[k][0]);
        if (w > 0) { res[0][1] *= 1 - w; res.push([hueso[tramos[k - 1][1]], w]); }
      }
      return res;
    }

    g.add(cuerpo);
    M.pielConHuesos(cuerpo, g, (i) => pesosTramos(Math.floor(i / (COLS + 1)) / FILAS, TRAMOS, MEZCLA));

    // ---------------- 3. EXTREMIDADES HERMÉTICAS (CERO PIEZAS ABIERTAS) ----------------
    function pataCerrada(s, camino, radios, huesosPata, nombre) {
      const curva = M.curva(camino);
      const tSeg = M.seg(20, 8);
      const rSeg = M.seg(24, 10);
      const geo = new THREE.TubeGeometry(curva, tSeg, 1, rSeg, false);
      const pos = geo.attributes.position;
      const P = new THREE.Vector3();

      for (let i = 0; i <= tSeg; i++) {
        const t = i / tSeg;
        curva.getPointAt(t, P);
        let r = M.interp(radios, t);
        // Cierre superior hermético en cúpula semiesférica dentro del cuerpo
        if (t < 0.22) {
          r *= Math.sqrt(Math.max(0, 1 - Math.pow(1 - t / 0.22, 2)));
        }
        for (let j = 0; j <= rSeg; j++) {
          const k = i * (rSeg + 1) + j;
          pos.setXYZ(k,
            P.x + (pos.getX(k) - P.x) * r,
            P.y + (pos.getY(k) - P.y) * r,
            P.z + (pos.getZ(k) - P.z) * r
          );
        }
      }
      const malla = M.coserNormales(M.pieza(geo, nombre, rSeg, tSeg));
      g.add(malla);

      const tramos = [
        [0, huesosPata[0]],
        [0.45, huesosPata[1]],
        [0.80, huesosPata[2]]
      ];
      M.pielConHuesos(malla, g, (i) => pesosTramos(Math.floor(i / (rSeg + 1)) / tSeg, tramos, 0.12));
      return malla;
    }

    LADOS.forEach((s) => {
      // Pata bípeda poderosa (nace arriba a y=0.58 dentro de la pelvis)
      const x = s * PIE_X;
      pataCerrada(s,
        [[x * 0.90, 0.58, -0.16], [x, 0.48, -0.16], [x, 0.32, -0.10], [x, 0.18, -0.14], [x, 0.05, -0.14]],
        [[0, 0.130], [0.25, 0.125], [0.55, 0.095], [0.80, 0.075], [1, 0.068]],
        ["Muslo" + L(s), "Pierna" + L(s), "Pata" + L(s)], "PiernaBipede");

      // Pie de terópodo: pie sólido cerrado con 3 garras pegadas directamente a la pata
      colgar("Pata" + L(s), bloque(x, 0.045, -0.115, 0.062, 0.038, 0.072, 0.8, "PlantaPie"));

      // Las 3 garras nacen pegadas directamente a la parte frontal de la pata y descienden curvadas al suelo
      [
        [-0.032, 0.042, -0.065, 0.88],  // Garra lateral externa
        [ 0.000, 0.046, -0.052, 1.00],  // Garra central prominente
        [ 0.032, 0.042, -0.065, 0.88]   // Garra interna
      ].forEach(([dx, yBase, zBase, lg]) => {
        const xg = x + s * dx;
        const finZ = zBase + 0.052 * lg;
        colgar("Pata" + L(s), punta([
          [xg, yBase, zBase],
          [xg + s * dx * 0.15, yBase * 0.65, zBase + 0.026 * lg],
          [xg + s * dx * 0.25, 0.003, finZ]
        ], 0.019 * lg, "GarraPie", 12, 8));
      });

      // Espolón trasero pegado al talón
      const xe = x - s * 0.026;
      colgar("Pata" + L(s), punta([
        [xe, 0.08, -0.14],
        [xe - s * 0.012, 0.05, -0.17],
        [xe - s * 0.016, 0.02, -0.20]
      ], 0.013, "Espolon", 8, 8));

      // Brazo terópodo
      const xb = s * BRAZO_X;
      pataCerrada(s,
        [[s * (BRAZO_X - 0.04), 0.54, 0.16], [xb, 0.46, 0.16], [s * (BRAZO_X + 0.02), 0.36, 0.22], [xb, 0.28, 0.26]],
        [[0, 0.075], [0.35, 0.070], [0.70, 0.055], [1, 0.048]],
        ["Brazo" + L(s), "Antebrazo" + L(s), "Mano" + L(s)], "BrazoTheropodo");

      // Mano base
      colgar("Mano" + L(s), bloque(xb, 0.27, 0.27, 0.038, 0.030, 0.042, 0.8, "ManoBase"));

      // LA GRAN GARRA CURVA DEL PULGAR (Baryonyx = "Garra Pesada")
      const xp = s * (BRAZO_X - 0.025);
      colgar("Mano" + L(s), punta([
        [xp, 0.27, 0.28],
        [xp - s * 0.012, 0.25, 0.35],
        [xp - s * 0.020, 0.19, 0.39],
        [xp - s * 0.016, 0.12, 0.36]
      ], 0.028, "GarraPulgarBaryonyx", 16, 10));

      // Otros dos dedos más pequeños
      [0.018, 0.036].forEach((dx, k) => {
        const xd = s * (BRAZO_X + dx);
        colgar("Mano" + L(s), punta([
          [xd, 0.26, 0.28],
          [xd + s * 0.006, 0.23, 0.33],
          [xd + s * 0.008, 0.19, 0.35]
        ], 0.016 - k * 0.003, "GarraMano", 12, 8));
      });
    });

    // ---------------- 4. CABEZA, HOCICO ALARGADO DE COCODRILO, MANDÍBULA Y DIENTES ----------------
    // Mandíbula inferior articulada alargada tipo cocodrilo con roseta que encaja en la superior
    const MAND_PERFIL = [
      // [z, y, semiancho, alto, forma]
      [0.46, 0.765, 0.120, 0.036, 2.2],  // Comisura trasera articulada
      [0.54, 0.752, 0.095, 0.034, 2.2],  // Detrás de los ojos
      [0.64, 0.742, 0.075, 0.030, 2.2],  // Estrechamiento medio tipo cocodrilo
      [0.74, 0.735, 0.054, 0.026, 2.2],  // Zona anterior delgada
      [0.82, 0.733, 0.050, 0.024, 2.2],  // Cintura mandibular
      [0.87, 0.738, 0.060, 0.024, 2.2],  // Roseta inferior que encaja
      [0.90, 0.742, 0.032, 0.016, 2.0],  // Remate punta barbilla
      [0.92, 0.744, 0.000, 0.000, 2.0]   // Cierre suave hermético
    ];

    const colsMand = M.seg(48, 20);
    const filasMand = M.seg(36, 16);
    const posMand = [];

    for (let r = 0; r <= filasMand; r++) {
      const t = r / filasMand;
      const f = t * (MAND_PERFIL.length - 1);
      const i = Math.min(MAND_PERFIL.length - 2, Math.floor(f));
      const e = f - i;
      const a = MAND_PERFIL[Math.max(0, i - 1)];
      const b = MAND_PERFIL[i];
      const c = MAND_PERFIL[i + 1];
      const d = MAND_PERFIL[Math.min(MAND_PERFIL.length - 1, i + 2)];

      const z = cr(a[0], b[0], c[0], d[0], e);
      const y = cr(a[1], b[1], c[1], d[1], e);
      const w = Math.max(0, cr(a[2], b[2], c[2], d[2], e));
      const h = Math.max(0, cr(a[3], b[3], c[3], d[3], e));
      const p = Math.max(1.8, cr(a[4], b[4], c[4], d[4], e));
      const ex = 2 / p;

      for (let col = 0; col <= colsMand; col++) {
        const fi = Math.PI + (col / colsMand) * Math.PI * 2;
        const sx = Math.sin(fi);
        const cy = Math.cos(fi);
        const hActual = cy > 0 ? h * 0.38 : h;
        const px = w * Math.sign(sx) * Math.pow(Math.abs(sx), ex);
        const py = y + hActual * cy;
        posMand.push(px, py, z);
      }
    }
    colgar("Mandibula", M.coserNormales(rejilla(posMand, colsMand, filasMand, "MandibulaBebé")));

    // Lengua rosada en el piso de la mandíbula alargada
    colgar("Mandibula", bloque(0, 0.748, 0.68, 0.038, 0.012, 0.140, 0.6, "Lengua"));

    // Dientecitos cónicos entrelazados tipo cocodrilo
    LADOS.forEach((s) => {
      // Dientes inferiores (encajando hacia arriba en el maxilar)
      [0.56, 0.63, 0.70, 0.76, 0.82, 0.87].forEach((z, idx) => {
        const esRoseta = idx >= 4;
        const wTeeth = esRoseta ? 0.052 : (0.092 - idx * 0.008);
        const xTeeth = s * wTeeth;
        const alt = esRoseta ? 0.018 : 0.015;
        const rad = esRoseta ? 0.007 : 0.0055;
        colgar("Mandibula", punta([[xTeeth, 0.750, z], [xTeeth, 0.750 + alt, z + 0.003]], rad, "DienteInferior", 8, 6));
      });

      // Dientes superiores colgando del hocico de cocodrilo
      [0.59, 0.66, 0.73, 0.79, 0.85, 0.88].forEach((z, idx) => {
        const esRoseta = idx >= 4;
        const wTeeth = esRoseta ? 0.058 : (0.095 - idx * 0.008);
        const xTeeth = s * wTeeth;
        const alt = esRoseta ? 0.020 : 0.016;
        const rad = esRoseta ? 0.0075 : 0.006;
        colgar("Cabeza", punta([[xTeeth, 0.768, z], [xTeeth, 0.768 - alt, z + 0.003]], rad, "DienteSuperior", 8, 6));
      });

      // Labio superior bordeando el hocico de cocodrilo
      const labioPuntos = [
        [s * 0.125, 0.772, 0.46],
        [s * 0.100, 0.768, 0.54],
        [s * 0.080, 0.762, 0.64],
        [s * 0.060, 0.755, 0.74],
        [s * 0.054, 0.750, 0.82],
        [s * 0.065, 0.748, 0.87],
        [s * 0.038, 0.748, 0.90],
        [s * 0.005, 0.748, 0.915]
      ];
      colgar("Cabeza", M.tubo(labioPuntos, 0.007, 0.005, { segLargo: 32, segRadio: 10, nombre: "LabioSuperior" }));
    });


    // Fosas nasales en el hocico de cocodrilo
    LADOS.forEach((s) => {
      colgar("Cabeza", bloque(s * 0.032, 0.810, 0.80, 0.008, 0.007, 0.010, 0.4, "FosaNasal", 10, 8));
    });

    // Ojos anime expresivos de agua
    LADOS.forEach((s) => {
      const ojoGrupo = new THREE.Group();
      ojoGrupo.position.set(s * 0.130, 0.875, 0.52);
      ojoGrupo.rotation.y = s * 0.38;

      // Córnea blanca
      ojoGrupo.add(almendra(0.052, 0.048, 0.014, "OjoBlanco"));

      // Iris azul turquesa / cyan brillante
      ojoGrupo.add(bloque(s * 0.004, 0, 0.006, 0.038, 0.038, 0.008, 1, "IrisAgua"));

      // Pupila profunda
      ojoGrupo.add(bloque(s * 0.004, -0.002, 0.012, 0.020, 0.022, 0.006, 1, "Pupila"));

      // Brillos especulares
      ojoGrupo.add(bloque(-s * 0.012, 0.014, 0.016, 0.014, 0.014, 0.005, 1, "BrilloOjo"));
      ojoGrupo.add(bloque(s * 0.012, -0.012, 0.015, 0.007, 0.007, 0.004, 1, "BrilloOjoPequeno"));

      // Párpados
      ojoGrupo.add(M.tubo([
        [-0.048, 0.006, 0.006],
        [0, 0.046, 0.012],
        [0.048, 0.006, 0.006]
      ], 0.008, 0.006, { segLargo: 10, segRadio: 8, nombre: "ParpadoSuperior" }));

      ojoGrupo.add(M.tubo([
        [-0.044, -0.006, 0.006],
        [0, -0.042, 0.010],
        [0.044, -0.006, 0.006]
      ], 0.006, 0.005, { segLargo: 10, segRadio: 8, nombre: "ParpadoInferior" }));

      colgar("Cabeza", ojoGrupo);
    });

    // ---------------- 5. PINTURA: PROYECCIÓN Y COLORES DE BARYONYX_DER.WEBP ----------------
    const TEXTURA = this.textura;
    const proyectar = M.proyeccion(TEXTURA, 0.92);

    const C_BASE_TERRACOTA = new THREE.Color(0xef9264);
    const C_CREMA_PECHO = new THREE.Color(0xfcf2db);
    const C_LENGUA = new THREE.Color(0xce6d5e);
    const MARFIL = new THREE.Color(0xeee3c6);
    const cColor = new THREE.Color();

    // Pintar cuerpo cerrado: todo el pecho, garganta y vientre en color crema claro oficial
    M.pintar(cuerpo, (i, p) => {
      proyectar(p.z, p.y, cColor);

      // Si cae en zona transparente o negra del fondo, salvaguarda con color base terracota
      if (cColor.r < 0.08 && cColor.g < 0.08 && cColor.b < 0.08) {
        cColor.copy(C_BASE_TERRACOTA);
      }

      const u = Math.floor(i / (COLS + 1)) / FILAS;
      const cIdx = i % (COLS + 1);
      const fi = Math.PI + (cIdx / COLS) * Math.PI * 2;
      const co = Math.cos(fi);

      // TODO EL PECHO Y LA GARGANTA DE COLOR CREMA
      if (p.z > -0.06 && p.z < 0.48 && co < 0.35) {
        const factorPecho = Math.min(1, Math.pow(Math.max(0, (0.35 - co) / 0.80), 1.1) * (1 - Math.min(1, Math.abs(p.x) / 0.16)));
        cColor.lerp(C_CREMA_PECHO, Math.max(0, factorPecho));
      }
      // Vientre bajo continuo entre las patas traseras
      else if (co < -0.15 && p.y < 0.58 && u > 0.12 && u < 0.88) {
        const factorVientre = Math.pow((-co - 0.15) / 0.85, 1.2) * suave(0.58, 0.35, p.y);
        cColor.lerp(C_CREMA_PECHO, Math.min(1, factorVientre * 0.92));
      }

      return cColor;
    }, g);

    // Pintar todas las piezas secundarias
    const COLOR_PIEZAS = {
      pierna: 0xdb774d,
      pie: 0xc4643d,
      brazo: 0xdb774d,
      mano: 0xc4643d,
      mandibula: 0xe88257,
            labio: 0xa84627,
      fosaNasal: 0x5a1e12,
      parpado: 0xb55130,
      iris: 0x06b6d4,
      pupila: 0x0f172a,
      brillo: 0xffffff,
      ojoBlanco: 0xfefcf9
    };

    const piezas = [];
    g.traverse((o) => { if (o.isMesh && o !== cuerpo) piezas.push(o); });

    piezas.forEach((o) => {
      if (/^(Diente|Garra|Espolon)/.test(o.name)) return M.pintar(o, () => MARFIL, g);
      if (o.name === "Lengua") return M.pintar(o, () => C_LENGUA, g);
      if (o.name === "OjoBlanco") return M.pintar(o, () => new THREE.Color(COLOR_PIEZAS.ojoBlanco), g);
      if (o.name === "IrisAgua") return M.pintar(o, () => new THREE.Color(COLOR_PIEZAS.iris), g);
      if (o.name === "Pupila") return M.pintar(o, () => new THREE.Color(COLOR_PIEZAS.pupila), g);
      if (/^BrilloOjo/.test(o.name)) return M.pintar(o, () => new THREE.Color(COLOR_PIEZAS.brillo), g);
      if (/^Parpado/.test(o.name)) return M.pintar(o, () => new THREE.Color(COLOR_PIEZAS.parpado), g);
      if (o.name === "LabioSuperior") return M.pintar(o, () => new THREE.Color(COLOR_PIEZAS.labio), g);
      if (o.name === "FosaNasal") return M.pintar(o, () => new THREE.Color(COLOR_PIEZAS.fosaNasal), g);
      if (o.name === "MandibulaBebé") {
        return M.pintar(o, (i, p) => {
          proyectar(p.z, p.y, cColor);
          if (cColor.r < 0.12 && cColor.g < 0.12 && cColor.b < 0.12) cColor.setHex(COLOR_PIEZAS.mandibula);
          if (p.y < 0.745) {
            cColor.lerp(C_CREMA_PECHO, suave(0.748, 0.725, p.y) * 0.88);
          }
          return cColor;
        }, g);
      }
      if (o.name === "PiernaBipede" || o.name === "PlantaPie" || o.name === "DedoPie") {
        return M.pintar(o, (i, p) => {
          proyectar(p.z, Math.max(p.y, 0.20), cColor);
          if (cColor.r < 0.08 && cColor.g < 0.08 && cColor.b < 0.08) cColor.setHex(COLOR_PIEZAS.pierna);
          return cColor;
        }, g);
      }
      if (o.name === "BrazoTheropodo" || o.name === "ManoBase") {
        return M.pintar(o, (i, p) => {
          proyectar(p.z, Math.max(p.y, 0.20), cColor);
          if (cColor.r < 0.08 && cColor.g < 0.08 && cColor.b < 0.08) cColor.setHex(COLOR_PIEZAS.brazo);
          return cColor;
        }, g);
      }

      // Por defecto proyectar con salvaguarda
      M.pintar(o, (i, p) => {
        proyectar(p.z, p.y, cColor);
        if (cColor.r < 0.08 && cColor.g < 0.08 && cColor.b < 0.08) cColor.copy(C_BASE_TERRACOTA);
        return cColor;
      }, g);
    });

    // ---------------- 6. ANIMACIONES BÍPEDAS CHIBI (THREE.AnimationMixer) ----------------
    const q = new THREE.Quaternion();
    const eu = new THREE.Euler();
    function giro(nombre, dur, fn, n = 32) {
      const tiempos = [];
      const valores = [];
      for (let i = 0; i <= n; i++) {
        const [x, y, z] = fn(i / n);
        eu.set(x * grad, y * grad, z * grad);
        q.setFromEuler(eu);
        tiempos.push(i * (dur / n));
        valores.push(q.x, q.y, q.z, q.w);
      }
      return new THREE.QuaternionKeyframeTrack("Hueso" + nombre + ".quaternion", tiempos, valores);
    }

    function sube(nombre, dur, fn, n = 32) {
      const tiempos = [];
      const valores = [];
      const [x0, y0, z0] = hueso[nombre].position.toArray();
      for (let i = 0; i <= n; i++) {
        tiempos.push(i * (dur / n));
        valores.push(x0, y0 + fn(i / n), z0);
      }
      return new THREE.VectorKeyframeTrack("Hueso" + nombre + ".position", tiempos, valores);
    }

    const sen = (t, c = 1) => Math.sin(t * Math.PI * 2 * c);
    const cos = (t, c = 1) => Math.cos(t * Math.PI * 2 * c);

    // Reposo: respiración suave, postura bípeda equilibrada y mecida dulce de la colita
    const dR = 3.0;
    const reposo = new THREE.AnimationClip("Reposo", dR, [
      sube("Cadera", dR, (t) => 0.010 * sen(t)),
      giro("Pecho", dR, (t) => [2.0 * sen(t), 0, 0]),
      giro("Cuello1", dR, (t) => [-2.5 * sen(t), 0, 0]),
      giro("Cuello2", dR, (t) => [-2.0 * sen(t), 0, 0]),
      giro("Cabeza", dR, (t) => [3.0 * sen(t), 3.5 * cos(t), 1.5 * sen(t)]),
      giro("Cola1", dR, (t) => [1.0 * sen(t), 4 * sen(t), 0]),
      giro("Cola2", dR, (t) => [2.0 * sen(t), 7 * sen(t), 0]),
      giro("Cola3", dR, (t) => [3.0 * sen(t), 11 * sen(t), 0]),
      ...LADOS.flatMap((s) => [
        giro("Brazo" + L(s), dR, (t) => [s * 2.5 * sen(t), 0, -s * 2.0 * cos(t)]),
        giro("Antebrazo" + L(s), dR, (t) => [s * 3.0 * sen(t), 0, 0]),
        giro("Muslo" + L(s), dR, (t) => [-1.5 * sen(t), 0, 0])
      ])
    ]);

    // Caminar: marcha bípeda ágil de carnívoro de agua
    const dC = 1.0;
    const PASO = 26;
    const caminar = new THREE.AnimationClip("Caminar", dC, [
      sube("Cadera", dC, (t) => 0.018 * (1 - cos(t, 2)) / 2),
      giro("Cadera", dC, (t) => [0, 5.0 * sen(t), 3.5 * cos(t)]),
      giro("Pecho", dC, (t) => [0, -4.0 * sen(t), -3.0 * cos(t)]),
      giro("Cuello1", dC, (t) => [4.5 * sen(t, 2), 0, 0]),
      giro("Cabeza", dC, (t) => [-5.0 * sen(t, 2), -5.0 * sen(t), 0]),
      giro("Cola1", dC, (t) => [0, -14 * sen(t), 0]),
      giro("Cola2", dC, (t) => [0, -22 * sen(t), 0]),
      giro("Cola3", dC, (t) => [0, -32 * sen(t), 0]),
      ...LADOS.flatMap((s) => [
        giro("Muslo" + L(s), dC, (t) => [s * PASO * sen(t), 0, 0]),
        giro("Pierna" + L(s), dC, (t) => [s * (PASO * 0.6) * Math.max(0, -sen(t)), 0, 0]),
        giro("Brazo" + L(s), dC, (t) => [s * -PASO * 0.7 * sen(t), 0, 0]),
        giro("Antebrazo" + L(s), dC, (t) => [s * -15 * sen(t), 0, 0])
      ])
    ]);

    // Rugir / Cazar: agacha el torso, abre ampliamente sus fauces de cocodrilo, echa los brazos atrás mostrando sus enormes garras y ruge
    const dG = 1.8;
    const alzar = [[0, 0], [0.22, 1], [0.75, 1], [1, 0]];
    const abrirBoca = [[0, 0], [0.25, 0], [0.40, 1], [0.70, 1], [0.85, 0], [1, 0]];
    const rugir = new THREE.AnimationClip("Rugir", dG, [
      sube("Cadera", dG, (t) => -0.025 * M.interp(alzar, t)),
      giro("Cadera", dG, (t) => [10 * M.interp(alzar, t), 0, 0]),
      giro("Pecho", dG, (t) => [14 * M.interp(alzar, t), 0, 0]),
      giro("Cuello1", dG, (t) => [-16 * M.interp(alzar, t), 0, 0]),
      giro("Cabeza", dG, (t) => [-12 * M.interp(alzar, t), 0, 0]),
      giro("Mandibula", dG, (t) => [32 * M.interp(abrirBoca, t), 0, 0]),
      giro("Cola1", dG, (t) => [10 * M.interp(alzar, t), 16 * sen(t, 2), 0]),
      giro("Cola2", dG, (t) => [15 * M.interp(alzar, t), 28 * sen(t, 2), 0]),
      giro("Cola3", dG, (t) => [20 * M.interp(alzar, t), 38 * sen(t, 2), 0]),
      ...LADOS.flatMap((s) => [
        giro("Brazo" + L(s), dG, (t) => [-35 * M.interp(alzar, t), s * 25 * M.interp(alzar, t), 0]),
        giro("Antebrazo" + L(s), dG, (t) => [-25 * M.interp(alzar, t), 0, 0]),
        giro("Mano" + L(s), dG, (t) => [-15 * M.interp(alzar, t), 0, 0]),
        giro("Muslo" + L(s), dG, (t) => [-8 * M.interp(alzar, t), 0, 0])
      ])
    ]);

    g.animations = [reposo, caminar, rugir];
    hueso.Raiz.userData.esqueleto = HUESOS.map(([nombre]) => "Hueso" + nombre);

    return g;
  },

  // Imagen de referencia reducida ×2, sin tinta (RGB en base64) para proyectar colores fieles de baryonyx_der.webp
  textura: {
    w: 260, h: 178, k: 2, esc: 0.00325, x0: 240, y0: 350,
    datos: ""
  }
});
